/** Information about pagination in a connection. */
export interface PageInfo {
  /** When paginating forwards, the cursor to continue. */
  endCursor?: string | null;
  /** When paginating forwards, are there more items? */
  hasNextPage: boolean;
  /** When paginating backwards, are there more items? */
  hasPreviousPage: boolean;
  /** When paginating backwards, the cursor to continue. */
  startCursor?: string | null;
}
/** A `MachineSession` edge in the connection. */
export interface MachineSessionEdge {
  cursor?: string | null;
  /** The `MachineSession` at the end of the edge. */
  node?: MachineSession | null;
}
/** A `Machine` edge in the connection. */
export interface MachineEdge {
  cursor?: string | null;
  /** The `Machine` at the end of the edge. */
  node?: Machine | null;
}
/** Table constraints */
export interface MetaConstraints {
  foreignKey: MetaForeignKeyConstraint[];
  primaryKey?: MetaPrimaryKeyConstraint | null;
  unique: MetaUniqueConstraint[];
}
/** Information about a table field/column */
export interface MetaField {
  /** PostgreSQL column name */
  columnName: string;
  description?: string | null;
  /** Enum metadata if this field has an enum type */
  enumValues?: MetaEnum | null;
  hasDefault: boolean;
  isForeignKey: boolean;
  isNotNull: boolean;
  isPrimaryKey: boolean;
  /** Final GraphQL field name */
  name: string;
  type: MetaType;
}
/** Information about a foreign key constraint */
export interface MetaForeignKeyConstraint {
  fields: MetaField[];
  name: string;
  refFields?: MetaField[] | null;
  refTable?: MetaRefTable | null;
  referencedFields: string[];
  referencedTable: string;
}
/** i18n metadata for a table with @i18n tag */
export interface MetaI18n {
  /** Fields that are translatable */
  translatableFields: MetaI18nField[];
  /** Name of the translation table */
  translationTable: string;
}
/** Information about a database index */
export interface MetaIndex {
  columns: string[];
  fields?: MetaField[] | null;
  isPrimary: boolean;
  isUnique: boolean;
  name: string;
}
/** Table inflection names */
export interface MetaInflection {
  allRows: string;
  conditionType: string;
  connection: string;
  createInputType: string;
  createPayloadType: string;
  deletePayloadType: string;
  edge: string;
  filterType?: string | null;
  orderByType: string;
  patchType?: string | null;
  tableType: string;
  updatePayloadType?: string | null;
}
/** Information about a primary key constraint */
export interface MetaPrimaryKeyConstraint {
  fields: MetaField[];
  name: string;
}
/** Table query/mutation names */
export interface MetaQuery {
  all?: string | null;
  create?: string | null;
  delete?: string | null;
  one?: string | null;
  update?: string | null;
}
/** Realtime metadata for a table with @realtime tag */
export interface MetaRealtime {
  /** The generated subscription field name (e.g. onPostChanged) */
  subscriptionFieldName: string;
}
/** Table relations */
export interface MetaRelations {
  belongsTo: MetaBelongsToRelation[];
  has: MetaHasRelation[];
  hasMany: MetaHasRelation[];
  hasOne: MetaHasRelation[];
  manyToMany: MetaManyToManyRelation[];
}
/** Provisioning scope metadata for a table */
export interface MetaScope {
  /** SQL name of the entity table for entity scopes, else null */
  entityTable?: string | null;
  /** Inflected scope key column (e.g. databaseId, orgId), null for global tiers */
  keyColumn?: string | null;
  /** Provisioning scope: 'platform', 'app', 'database', or an entity scope (e.g. 'org') */
  scope: string;
  /** Provenance of the scope metadata (always 'smartTag') */
  source: string;
  /** Coarse bucket: 'global', 'database', or 'entity' */
  tier: string;
}
/** Search metadata for a table */
export interface MetaSearch {
  /** Active search algorithms on this table */
  algorithms: string[];
  /** Searchable columns with their algorithm */
  columns: MetaSearchColumn[];
  /** Per-table search configuration */
  config?: MetaSearchConfig | null;
  /** Whether unifiedSearch composite filter is available */
  hasUnifiedSearch: boolean;
}
/** Storage metadata for a table */
export interface MetaStorage {
  /** GraphQL type name of the plane's buckets table */
  bucketsType: string;
  /** Computed download-URL field on the files type; null on the buckets side */
  downloadUrlField?: string | null;
  /** GraphQL type name of the plane's files table */
  filesType: string;
  /** Whether this table is a storage buckets table */
  isBucketsTable: boolean;
  /** Whether this table is a storage files table */
  isFilesTable: boolean;
  /** The plane's GraphQL upload surface */
  upload: MetaStorageUpload;
}
/** Information about a unique constraint */
export interface MetaUniqueConstraint {
  fields: MetaField[];
  name: string;
}
/** Information about a PostgreSQL enum type */
export interface MetaEnum {
  /** The PostgreSQL enum type name */
  name: string;
  /** Allowed values for this enum */
  values: string[];
}
/** Information about a PostgreSQL type */
export interface MetaType {
  /** Scalar serialization contract (null for plain scalars) */
  encoding?: MetaScalarEncoding | null;
  gqlType: string;
  hasDefault?: boolean | null;
  isArray: boolean;
  isNotNull?: boolean | null;
  pgType: string;
  subtype?: string | null;
}
/** Reference to a related table */
export interface MetaRefTable {
  name: string;
}
/** A translatable field */
export interface MetaI18nField {
  /** GraphQL field name */
  name: string;
  /** PostgreSQL column type (text, citext) */
  type: string;
}
/** A belongs-to (forward FK) relation */
export interface MetaBelongsToRelation {
  fieldName?: string | null;
  isUnique: boolean;
  keys: MetaField[];
  references: MetaRefTable;
  type?: string | null;
}
/** A has-one or has-many (reverse FK) relation */
export interface MetaHasRelation {
  fieldName?: string | null;
  isUnique: boolean;
  keys: MetaField[];
  referencedBy: MetaRefTable;
  type?: string | null;
}
/** A many-to-many relation via junction table */
export interface MetaManyToManyRelation {
  fieldName?: string | null;
  junctionLeftConstraint: MetaForeignKeyConstraint;
  junctionLeftKeyAttributes: MetaField[];
  junctionRightConstraint: MetaForeignKeyConstraint;
  junctionRightKeyAttributes: MetaField[];
  junctionTable: MetaRefTable;
  leftKeyAttributes: MetaField[];
  rightKeyAttributes: MetaField[];
  rightTable: MetaRefTable;
  type?: string | null;
}
/** A searchable column with its algorithm */
export interface MetaSearchColumn {
  /** Search algorithm: tsvector, bm25, trgm, or vector */
  algorithm: string;
  /** Column name (camelCase) */
  name: string;
}
/** Per-table search configuration from @searchConfig smart tag */
export interface MetaSearchConfig {
  /** Exponential decay factor per day */
  boostRecencyDecay?: number | null;
  /** Field used for recency decay */
  boostRecencyField?: string | null;
  /** Whether recency boosting is enabled */
  boostRecent: boolean;
  /** JSON-encoded per-adapter score weights */
  weights?: string | null;
}
/** The GraphQL upload surface of a storage plane, derived from the registry facts the presigned-url plugin emits from */
export interface MetaStorageUpload {
  /** Per-file input type inside the bulk input */
  bulkFileInputType: string;
  /** Per-file payload type inside the bulk payload */
  bulkFilePayloadType: string;
  /** Input type of the bulk upload mutation */
  bulkInputType: string;
  /** Root mutation field for bulk upload */
  bulkMutation: string;
  /** Payload type of the bulk upload mutation */
  bulkPayloadType: string;
  /** Input type of the single upload mutation */
  inputType: string;
  /** Root mutation field for single-file upload (e.g. uploadAppFile) */
  mutation: string;
  /** Payload type of the single upload mutation */
  payloadType: string;
  /** Whether the upload input requires ownerId (entity-keyed plane) */
  requiresOwnerId: boolean;
}
/** How a client must serialize/parse a scalar — the one field-type detail standard GraphQL introspection cannot describe. Null for plain scalars whose wire format is obvious from gqlType. */
export interface MetaScalarEncoding {
  /** For 'vector': declared length, else null. */
  dimensions?: number | null;
  /** For 'ltree': values are dot-separated path strings. */
  dotPath?: boolean | null;
  /** For 'vector': element scalar (e.g. 'float'). */
  elementType?: string | null;
  /** For 'geojson': Point/LineString/Polygon/…, else null. */
  geometrySubtype?: string | null;
  /** Machine kind: bigint, datetime, date, time, interval, uuid, geojson, point, inet, ltree, vector, bytea, or composite. */
  kind: string;
  /** For 'geojson': spatial reference id, else null. */
  srid?: number | null;
}
